package ru.n08i40k.reflection.generator

import kotlin.reflect.KClass

/**
 * Describes members of [value] whose accessors are generated by reflection-processor.
 *
 * The annotated interface is only a description: its properties and functions are never implemented.
 * Generated properties are named `Owner$member` and placed into the `Accessors.kt` file of the interface package.
 */
@Target(AnnotationTarget.CLASS)
@Retention(AnnotationRetention.SOURCE)
public annotation class Mirror(val value: KClass<*>)

/**
 * Same as [Mirror] for a class that cannot be referenced statically (private, missing in some clients, ...).
 *
 * Generates a `Class<*>` property for [binaryName], e.g. `org.telegram.ui.CalendarActivity$MonthView`.
 */
@Target(AnnotationTarget.CLASS)
@Retention(AnnotationRetention.SOURCE)
public annotation class RuntimeMirror(val binaryName: String)

/**
 * Field getter. [retype] is `[R, P...]` for MethodHandle.asType: the return type first, then parameter types.
 */
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.SOURCE)
public annotation class Getter(val retype: Array<KClass<*>> = [])

/**
 * Field setter, the property is named `Owner$field$$setter`. [retype] has the same meaning as in [Getter].
 */
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.SOURCE)
public annotation class Setter(val retype: Array<KClass<*>> = [])

/** ClonableFields of the owner class, the property is named `Owner$$fields`. */
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.SOURCE)
public annotation class Fields

/** The function describes a constructor, the property is named `Owner$$init`. */
@Target(AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.SOURCE)
public annotation class Constructor

/** MethodHandle.asType for a method or constructor: the return type first, then parameter types. */
@Target(AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.SOURCE)
public annotation class Retype(vararg val types: KClass<*>)

/** The member appeared in client [version]; its property gets the `$$<version>` suffix and is nullable. */
@Target(AnnotationTarget.CLASS, AnnotationTarget.PROPERTY, AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.SOURCE)
public annotation class Since(val version: String)

/** The member is absent since client [version]; its property is nullable. */
@Target(AnnotationTarget.CLASS, AnnotationTarget.PROPERTY, AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.SOURCE)
public annotation class Before(val version: String)

/** The member may be absent regardless of the version (e.g. exists only in some forks); its property is nullable. */
@Target(AnnotationTarget.CLASS, AnnotationTarget.PROPERTY, AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.SOURCE)
public annotation class Optional

/** Parameter of a class declared with [RuntimeMirror] of the same [binaryName]. */
@Target(AnnotationTarget.VALUE_PARAMETER)
@Retention(AnnotationRetention.SOURCE)
public annotation class Type(val binaryName: String)

/** JVM name of the member when it differs from the Kotlin declaration name. */
@Target(AnnotationTarget.PROPERTY, AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.SOURCE)
public annotation class Name(val value: String)
